import urllib.request, json, sys

API = "http://localhost:3000/api/songs"

def post(title, artist, lyrics):
    data = json.dumps({"title": title, "artist": artist, "lyrics": lyrics}).encode()
    req = urllib.request.Request(API, data=data, headers={"Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req) as r:
            result = json.loads(r.read())
            print(f"✓ {artist} - {title}")
            return result
    except Exception as e:
        print(f"✗ {artist} - {title}: {e}")

